use ocas::ocas_rewrite::rules::default_rules; fn main() { let arena = Arena::new(); let ctx = AtomArena::new(&arena); // Parse the expression let expr = parse(&ctx, "x^2").unwrap(); // Differentiate let d = diff(&ctx, expr, Symbol::new("x")); println!("derivative: {}", d); // Output: 2*x // Simplify (default rule set: identity removal, constant folding) let e2 = parse(&ctx, "x + 0 + y*0 + z*1").unwrap(); let rules = default_rules(&ctx, &()); let s = simplify(&ctx, e2, &rules, 100); println!("simplified: {}", s); // Output: x + z
