}; fn main() { println!("is_prime(97) = {}", is_prime(&97.into())); // Output: is_prime(97) = true let factors = factor_integer(&360.into()); println!("360 = {}", factors.iter() .map(|(p, e)| format!("{}^{}", p, e)) .collect::<Vec<_>>() .join(" × ")); // Output: 360 = 2^3 × 3^2 × 5^1 println!("φ(360) = {}", euler_phi(&360.into())); // Output: φ(360) = 96
