// x + y = 3 → x = 1, y = 2
let a = Matrix::from_rows( vec![vec![Integer::from(2), Integer::from(1)], vec![Integer::from(1), Integer::from(1)]], d,
);
let b = vec![Integer::from(4), Integer::from(3)];
let x = a.solve(&b).unwrap();
assert_eq!(x, vec![Integer::from(1), Integer::from(2)]); 3×3 system : use ocas_domain::{Integer, IntegerDomain};
