use ocas_calc::integrate_heuristic;
use ocas_core::arena::Arena; let arena = Arena::new();
let ctx = AtomArena::new(&arena);
let x = ctx.var("x"); // ∫ x·exp(x) dx — integration by parts (LIATE: x=algebraic, exp=exponential)
let expr = ctx.mul(&[x, ctx.fun("exp", &[x])]);
