let pat = Pattern::Wildcard(Symbol::new("x"), WildcardLevel::Single);
let rule = Rule::new(pat, |bindings: &Bindings, _ctx: &AtomArena| { let x = bindings.get(Symbol::new("x")).unwrap(); let MatchValue::Single(v) = x else { panic!("expected single"); }; _ctx.mul(&[_ctx.num(2), *v])
}); let y = ctx.var("y");
let result = rule.apply(&ctx, y).unwrap();
assert_eq!(result.to_string(), "2*y"); Rule::with_condition pub fn with_condition<F>(self, condition: F) -> Self
where F: Fn(&Bindings<'a>) -> bool + 'a, Function : Adds a precondition to the rule. The condition is evaluated after a successful match, before the replacement. Parameters : Parameter Type Description condition Fn(&Bindings) -> bool The condition closure; the replacement runs only when it returns true Return value : Rule<'a> — a rule with a condition. Example : use ocas_atom::AtomArena;
