let rule = Rule::new(pat, |_bindings: &Bindings, ctx: &AtomArena| { ctx.num(99)
}).with_condition(|bindings: &Bindings| { let x = bindings.get(Symbol::new("x")).unwrap(); let MatchValue::Single(v) = x else { return false; }; v.to_string() == "y"
}); let y = ctx.var("y");
let z = ctx.var("z");
