let ctx = AtomArena::new(&arena);
let rules = default_rules(&ctx, &()); let x = ctx.var("x");
let expr = ctx.mul(&[x, ctx.num(0)]);
let result = simplify(&ctx, expr, &rules, 10);
assert_eq!(result.to_string(), "0"); See also : simplify_with_fuel, default_rules, Rule

