let a = Tensor::new(Symbol::new("A"), vec![ IndexSlot::new(ctx.var("mu"), IndexPosition::Upper), IndexSlot::new(ctx.var("nu"), IndexPosition::Lower),
]);
let b = Tensor::new(Symbol::new("B"), vec![ IndexSlot::new(ctx.var("nu"), IndexPosition::Upper), IndexSlot::new(ctx.var("rho"), IndexPosition::Lower),
]);
match contract(&ctx, &a, &b) { Contracted::Product(tp) => { assert_eq!(tp.factors.len(), 1); assert_eq!(tp.factors[0].rank(), 2); // mu, rho } Contracted::Scalar(_) => panic!("expected partial contraction"),
}
// Output: partial contraction, 2 free indices remain

