Signature : pub fn refresh_dummies<'a>( ctx: &'a AtomArena<'a>, expr: Atom<'a>, registry: &TensorRegistry,
) -> Result<Atom<'a>, DummyError> Description : Renames the dummy indices in a tensor expression to avoid conflicts with external (free) indices. Labels that occur exactly twice (once as a superscript, once as a subscript) are replaced with new names assigned per dimension group (d0, d1, …). External indices remain unchanged. Parameters : Parameter Type Description ctx &'a AtomArena<'a> The expression arena expr Atom<'a> The tensor expression to process registry &TensorRegistry The tensor registry (used for dimension-group assignment) Returns : Result<Atom<'a>, DummyError> Errors : Error variant Description OverContracted(Symbol) An index label occurs more than twice BadContraction(Symbol) Two slots with the same label have the same variance Example : use ocas_atom::tensor::spec::{SymmetrySpec, TensorRegistry};
use ocas_atom::tensor::dummy::refresh_dummies;
use ocas_atom::{AtomArena, Symbol};
use ocas_core::arena::Arena; let arena = Arena::new();
let ctx = AtomArena::new(&arena);
let mut reg = TensorRegistry::new();
reg.register(Symbol::new("T"), SymmetrySpec::none());
reg.register(Symbol::new("U"), SymmetrySpec::none()); // T(i,j) * U(j,i): i and j both occur exactly twice → dummy indices
let expr = ctx.mul(&[ctx.fun("T", &[ctx.var("i"), ctx.var("j")]), ctx.fun("U", &[ctx.var("j"), ctx.var("i")])]);
let refreshed = refresh_dummies(&ctx, expr, &reg).unwrap();
println!("{}", refreshed);
// Output: dummy indices renamed to d0, d1 (assigned per dimension group) See also : DummyError , TensorRegistry

