pub fn eliminate<D: Domain + 'static>( ideal: &[SparseMultivariatePolynomial<D, Lex>], elim_vars: usize, algo: Algorithm,
) -> GroebnerBasis<D, Lex> Description : Eliminates variables from an ideal. Returns a Gröbner basis of $I \cap k[x_{\text{elim_vars}}, \dots, x_{n-1}]$, i.e., the polynomials that do not contain the first elim_vars variables. Uses the Lex order — under Lex, the reduced Gröbner basis of an ideal automatically contains generators of the elimination ideal. Parameters : Parameter Type Description ideal &[SparseMultivariatePolynomial<D, Lex>] The generators of the ideal (must be in Lex order) elim_vars usize The number of variables to eliminate (eliminates $x_0, \dots, x_{\text{elim_vars}-1}$) algo Algorithm Gröbner basis algorithm selection Returns : GroebnerBasis<D, Lex> — a Gröbner basis of the elimination ideal. Example : use ocas_domain::{RationalDomain, Rational};
use ocas_poly::sparse::Lex;
use ocas_poly::{SparseMultivariatePolynomial, eliminate, Algorithm}; let d = RationalDomain;
// Ideal: x + y + z, x*y + x*z in k[x,y,z]; eliminate x
let f1 = SparseMultivariatePolynomial::<_, Lex>::from_terms(d, 3, vec![ (vec![1, 0, 0], Rational::new(1, 1)), (vec![0, 1, 0], Rational::new(1, 1)), (vec![0, 0, 1], Rational::new(1, 1)),
]);
let f2 = SparseMultivariatePolynomial::<_, Lex>::from_terms(d, 3, vec![ (vec![1, 1, 0], Rational::new(1, 1)), (vec![1, 0, 1], Rational::new(1, 1)),
]);
let elim = eliminate(&[f1, f2], 1, Algorithm::Auto);
// The result should lie in k[y,z]
for p in &elim.basis { assert!(p.degree_in(0) == 0, "the eliminated variable x should not appear");
} See also : groebner_basis , ideal_quotient

