Signature : pub fn resultant(&self, other: &Self) -> D::Element Description : Computes the resultant $\operatorname{Res}(a, b)$ of two univariate polynomials using the Brown PRS (polynomial remainder sequence) algorithm. Parameters : Parameter Type Description other &Self The other polynomial Returns : D::Element — the resultant scalar. It is zero if and only if $\gcd(a, b)$ is non-constant. Algorithm : subresultant PRS (Brown), with an exact division by $\beta$ at each step (the subresultant theorem guarantees exactness in a UFD). Example : use ocas_domain::{IntegerDomain, Integer};
use ocas_poly::DenseUnivariatePolynomial; let d = IntegerDomain;
// Res(x - 1, x - 2) = 1 - 2 = -1
let a = DenseUnivariatePolynomial::from_coeffs(d, vec![ Integer::from(-1), Integer::from(1),
]);
let b = DenseUnivariatePolynomial::from_coeffs(d, vec![ Integer::from(-2), Integer::from(1),
]);
assert_eq!(a.resultant(&b), Integer::from(-1));
// Output: -1 Example (with a common root) : use ocas_domain::{IntegerDomain, Integer};
use ocas_poly::DenseUnivariatePolynomial; let d = IntegerDomain;
// x - 1 and x^2 - 1 share the root x = 1
let a = DenseUnivariatePolynomial::from_coeffs(d, vec![ Integer::from(-1), Integer::from(1),
]);
let b = DenseUnivariatePolynomial::from_coeffs(d, vec![ Integer::from(-1), Integer::from(0), Integer::from(1),
]);
assert_eq!(a.resultant(&b), Integer::from(0));
// Output: 0 (they share the factor x - 1) See also : Resultants and subresultant PRS

