use ocas_poly::rational::RationalPolynomial;
use ocas_poly::Grevlex; let d = IntegerDomain;
let n_vars = 2; // x / y
let num: SparseMultivariatePolynomial<_, Grevlex> = SparseMultivariatePolynomial::from_terms(d, n_vars, vec![(vec![1, 0], Integer::from(1))]);
let den: SparseMultivariatePolynomial<_, Grevlex> = SparseMultivariatePolynomial::from_terms(d, n_vars, vec![(vec![0, 1], Integer::from(1))]);
let f = RationalPolynomial::from_num_den(num, den); // y / x
let num2: SparseMultivariatePolynomial<_, Grevlex> = SparseMultivariatePolynomial::from_terms(d, n_vars, vec![(vec![0, 1], Integer::from(1))]);
let den2: SparseMultivariatePolynomial<_, Grevlex> = SparseMultivariatePolynomial::from_terms(d, n_vars, vec![(vec![1, 0], Integer::from(1))]);
let g = RationalPolynomial::from_num_den(num2, den2); // (x/y) * (y/x) = 1
let h = f.mul(&g);
assert!(h.is_one());
// Output: 1 See also : RationalPolynomial definition

